import{_ as e,o,c as i,ae as t}from"./chunks/framework.vXWZTEWX.js";const b=JSON.parse('{"title":"Capítulo 1: Introducción y Objetivos","description":"","frontmatter":{},"headers":[],"relativePath":"tfm/01_introduccion_objetivos.md","filePath":"tfm/01_introduccion_objetivos.md"}'),n={name:"tfm/01_introduccion_objetivos.md"};function r(s,a,c,l,d,u){return o(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="capitulo-1-introduccion-y-objetivos" tabindex="-1">Capítulo 1: Introducción y Objetivos <a class="header-anchor" href="#capitulo-1-introduccion-y-objetivos" aria-label="Permalink to &quot;Capítulo 1: Introducción y Objetivos&quot;">​</a></h1><h2 id="_1-1-contexto" tabindex="-1">1.1. Contexto <a class="header-anchor" href="#_1-1-contexto" aria-label="Permalink to &quot;1.1. Contexto&quot;">​</a></h2><p>La contratación pública es un pilar fundamental de la economía, representando un porcentaje significativo del PIB. Sin embargo, la burocracia asociada a la validación de propuestas técnicas crea cuellos de botella que retrasan la ejecución de proyectos vitales.</p><h2 id="_1-2-motivacion" tabindex="-1">1.2. Motivación <a class="header-anchor" href="#_1-2-motivacion" aria-label="Permalink to &quot;1.2. Motivación&quot;">​</a></h2><p>La motivación de <strong>TenderCheck AI</strong> nace de la necesidad de modernizar la administración pública (LegalTech), aplicando tecnologías de vanguardia (IA Generativa) a problemas administrativos clásicos, pero con un enfoque ético y privado (Local IA).</p><h2 id="_1-3-objetivos" tabindex="-1">1.3. Objetivos <a class="header-anchor" href="#_1-3-objetivos" aria-label="Permalink to &quot;1.3. Objetivos&quot;">​</a></h2><h3 id="_1-3-1-objetivo-general" tabindex="-1">1.3.1. Objetivo General <a class="header-anchor" href="#_1-3-1-objetivo-general" aria-label="Permalink to &quot;1.3.1. Objetivo General&quot;">​</a></h3><p>Desarrollar un prototipo funcional de software capaz de asistir a los técnicos de la administración en la validación de solvencia técnica de las ofertas presentadas a concursos públicos.</p><h3 id="_1-3-2-objetivos-especificos" tabindex="-1">1.3.2. Objetivos Específicos <a class="header-anchor" href="#_1-3-2-objetivos-especificos" aria-label="Permalink to &quot;1.3.2. Objetivos Específicos&quot;">​</a></h3><ol><li><strong>Ingeniería de Datos</strong>: Implementar un pipeline capaz de extraer texto estructurado de PDFs complejos (tablas, columnas).</li><li><strong>Inteligencia Artificial</strong>: Integrar y optimizar un modelo de lenguaje local (Ollama) para la extracción de requisitos sin costes de API.</li><li><strong>Experiencia de Usuario</strong>: Diseñar una interfaz intuitiva que permita la carga de documentos y visualice los resultados con claridad (Semáforos de cumplimiento).</li><li><strong>Seguridad</strong>: Garantizar la autenticación de usuarios y la persistencia segura de las sesiones de trabajo.</li><li><strong>Arquitectura</strong>: Construir el sistema bajo principios de <em>Clean Architecture</em> para asegurar su mantenibilidad y escalabilidad futura.</li></ol>',10)])])}const m=e(n,[["render",r]]);export{b as __pageData,m as default};
